declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/helpers.php';
requireLogin();
function c4e($v): string { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function c4back(string $file): void { header('Location: '.appUrl('/c4gmod/'.$file)); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){c4gmod_check_csrf();if(isset($_POST['delete']))$pdo->prepare("UPDATE c4gmod_api_tokens SET active=0 WHERE id=?")->execute([(int)$_POST['id']]);else{$name=trim((string)($_POST['name']??'C4GMOD'));$raw=bin2hex(random_bytes(32));$pdo->prepare("INSERT INTO c4gmod_api_tokens(name,token_hash) VALUES(?,?)")->execute([$name,hash('sha256',$raw)]);header('Location: '.appUrl('/c4gmod/tokens.php?new='.urlencode($raw)));exit;}c4back('tokens.php');}$rows=$pdo->query("SELECT id,name,created_at,last_used_at,active FROM c4gmod_api_tokens ORDER BY id DESC")->fetchAll();$pageTitle='C4GMOD - Token API';$activePage='c4g';?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Token API C4GMOD</title><link rel="stylesheet" href="<?=c4e(appUrl('/assets/css/style.css'))?>"></head><body><div class="dashboard"><?php require __DIR__.'/../includes/menu.php';?><main class="main-content"><?php require __DIR__.'/../includes/header.php';?><div class="container-form"><h1>Token API <span>C4GMOD</span></h1><?php if(!empty($_GET['new'])):?><div class="success">Token gerado. Guarde-o agora:<br><code><?=c4e($_GET['new'])?></code></div><p>URL do APK:</p><input value="<?=c4e(appUrl('/api/c4gmod.php'))?>?token=<?=c4e($_GET['new'])?>" readonly><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=c4e(c4gmod_csrf_token())?>"><label>Nome</label><input name="name" value="C4GMOD"><button class="btn">Gerar token</button></form><div class="table-container" style="margin-top:20px"><table><tr><th>Nome</th><th>Criado</th><th>Último uso</th><th>Ação</th></tr><?php foreach($rows as $r):?><tr><td><?=c4e($r['name'])?></td><td><?=c4e($r['created_at'])?></td><td><?=c4e($r['last_used_at']??'')?></td><td><?php if($r['active']):?><form method="post"><input type="hidden" name="csrf" value="<?=c4e(c4gmod_csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-delete" name="delete">Revogar</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></main></div></body></html>